CREATE TYPE public.app_role AS ENUM ('super_admin','teacher','student');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND p.active) $$;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'super_admin'));
CREATE FUNCTION public.create_school_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name','')); RETURN NEW; END $$;
CREATE TRIGGER school_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_school_profile();
CREATE TABLE public.academic_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.academic_sessions TO authenticated; GRANT ALL ON public.academic_sessions TO service_role; ALTER TABLE public.academic_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.classes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, level integer NOT NULL CHECK(level BETWEEN 3 AND 10));
GRANT SELECT ON public.classes TO authenticated; GRANT ALL ON public.classes TO service_role; ALTER TABLE public.classes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES public.classes(id), name text NOT NULL, UNIQUE(class_id,name));
GRANT SELECT ON public.sections TO authenticated; GRANT ALL ON public.sections TO service_role; ALTER TABLE public.sections ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.subjects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, code text NOT NULL);
GRANT SELECT ON public.subjects TO authenticated; GRANT ALL ON public.subjects TO service_role; ALTER TABLE public.subjects ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.students(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid UNIQUE REFERENCES public.profiles(id), uid text UNIQUE NOT NULL CHECK(uid ~ '^[a-z0-9_-]{2,50}$'), full_name text NOT NULL, section_id uuid NOT NULL REFERENCES public.sections(id), session_id uuid NOT NULL REFERENCES public.academic_sessions(id), active boolean NOT NULL DEFAULT true, is_demo boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.students TO authenticated; GRANT ALL ON public.students TO service_role; ALTER TABLE public.students ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.teachers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid UNIQUE REFERENCES public.profiles(id), username text UNIQUE NOT NULL, full_name text NOT NULL, active boolean NOT NULL DEFAULT true, is_demo boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.teachers TO authenticated; GRANT ALL ON public.teachers TO service_role; ALTER TABLE public.teachers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.teacher_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), teacher_id uuid NOT NULL REFERENCES public.teachers(id), section_id uuid NOT NULL REFERENCES public.sections(id), subject_id uuid NOT NULL REFERENCES public.subjects(id), UNIQUE(section_id,subject_id));
GRANT SELECT ON public.teacher_assignments TO authenticated; GRANT ALL ON public.teacher_assignments TO service_role; ALTER TABLE public.teacher_assignments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.examinations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, session_id uuid NOT NULL REFERENCES public.academic_sessions(id), start_date date NOT NULL, end_date date NOT NULL, status text NOT NULL DEFAULT 'MARKS_ENTRY_IN_PROGRESS' CHECK(status IN ('DRAFT','MARKS_ENTRY_IN_PROGRESS','SUBMITTED','READY_FOR_PUBLICATION','SCHEDULED','PUBLISHED','REOPENED')), scheduled_at timestamptz, scheduled_by uuid REFERENCES public.profiles(id), published_at timestamptz, archived boolean NOT NULL DEFAULT false, is_demo boolean NOT NULL DEFAULT false, grade_rules jsonb NOT NULL DEFAULT '[{"min":90,"grade":"A+"},{"min":80,"grade":"A"},{"min":70,"grade":"B+"},{"min":60,"grade":"B"},{"min":50,"grade":"C"},{"min":35,"grade":"D"},{"min":0,"grade":"E"}]');
GRANT SELECT ON public.examinations TO authenticated; GRANT ALL ON public.examinations TO service_role; ALTER TABLE public.examinations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.exam_subjects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), examination_id uuid NOT NULL REFERENCES public.examinations(id), assignment_id uuid NOT NULL REFERENCES public.teacher_assignments(id), max_marks numeric NOT NULL DEFAULT 100 CHECK(max_marks>0), passing_marks numeric NOT NULL DEFAULT 35 CHECK(passing_marks>=0 AND passing_marks<=max_marks), allow_decimal boolean NOT NULL DEFAULT false, allow_exempt boolean NOT NULL DEFAULT false, submitted_at timestamptz, UNIQUE(examination_id,assignment_id));
GRANT SELECT ON public.exam_subjects TO authenticated; GRANT ALL ON public.exam_subjects TO service_role; ALTER TABLE public.exam_subjects ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.marks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_subject_id uuid NOT NULL REFERENCES public.exam_subjects(id), student_id uuid NOT NULL REFERENCES public.students(id), obtained numeric, status text NOT NULL DEFAULT 'PRESENT' CHECK(status IN ('PRESENT','AB','EXEMPT')), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(exam_subject_id,student_id), CHECK((status='PRESENT' AND obtained IS NOT NULL AND obtained>=0) OR (status<>'PRESENT' AND obtained IS NULL)));
GRANT SELECT ON public.marks TO authenticated; GRANT ALL ON public.marks TO service_role; ALTER TABLE public.marks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.marksheet_publications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), examination_id uuid NOT NULL REFERENCES public.examinations(id), admin_id uuid REFERENCES public.profiles(id), action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.marksheet_publications TO authenticated; GRANT ALL ON public.marksheet_publications TO service_role; ALTER TABLE public.marksheet_publications ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES public.profiles(id), action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE INDEX marks_student_idx ON public.marks(student_id); CREATE INDEX assignment_teacher_idx ON public.teacher_assignments(teacher_id); CREATE INDEX students_section_idx ON public.students(section_id); CREATE INDEX exam_subject_exam_idx ON public.exam_subjects(examination_id);
CREATE FUNCTION public.is_assigned(_section uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'teacher') AND EXISTS(SELECT 1 FROM public.teacher_assignments a JOIN public.teachers t ON t.id=a.teacher_id WHERE a.section_id=_section AND t.profile_id=auth.uid() AND t.active) $$;
CREATE FUNCTION public.can_read_sheet(_sheet uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'super_admin') OR (public.has_role(auth.uid(),'teacher') AND EXISTS(SELECT 1 FROM public.exam_subjects es JOIN public.teacher_assignments a ON a.id=es.assignment_id JOIN public.teachers t ON t.id=a.teacher_id WHERE es.id=_sheet AND t.profile_id=auth.uid() AND t.active)) $$;
CREATE POLICY students_read ON public.students FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin') OR (profile_id=auth.uid() AND public.has_role(auth.uid(),'student')) OR public.is_assigned(section_id));
CREATE POLICY teachers_read ON public.teachers FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin') OR profile_id=auth.uid());
CREATE POLICY assignments_read ON public.teacher_assignments FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM public.teachers t WHERE t.id=teacher_id AND t.profile_id=auth.uid()));
CREATE POLICY sheets_read ON public.exam_subjects FOR SELECT TO authenticated USING(public.can_read_sheet(id) OR (public.has_role(auth.uid(),'student') AND EXISTS(SELECT 1 FROM public.examinations e JOIN public.teacher_assignments a ON a.id=assignment_id JOIN public.students s ON s.section_id=a.section_id WHERE e.id=examination_id AND e.status='PUBLISHED' AND s.profile_id=auth.uid() AND s.session_id=e.session_id AND s.active)));
CREATE POLICY marks_read ON public.marks FOR SELECT TO authenticated USING(public.can_read_sheet(exam_subject_id) OR (public.has_role(auth.uid(),'student') AND EXISTS(SELECT 1 FROM public.students s JOIN public.exam_subjects es ON es.id=exam_subject_id JOIN public.examinations e ON e.id=es.examination_id WHERE s.id=student_id AND s.profile_id=auth.uid() AND s.active AND e.status='PUBLISHED')));
CREATE POLICY exams_read ON public.examinations FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'teacher') OR public.has_role(auth.uid(),'student'));
CREATE POLICY sessions_read ON public.academic_sessions FOR SELECT TO authenticated USING(auth.uid() IS NOT NULL);
CREATE POLICY classes_read ON public.classes FOR SELECT TO authenticated USING(auth.uid() IS NOT NULL);
CREATE POLICY sections_read ON public.sections FOR SELECT TO authenticated USING(auth.uid() IS NOT NULL);
CREATE POLICY subjects_read ON public.subjects FOR SELECT TO authenticated USING(auth.uid() IS NOT NULL);
CREATE POLICY publications_read ON public.marksheet_publications FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE POLICY audit_read ON public.audit_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE FUNCTION public.exam_validation(_exam uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE sheets integer; done integer; missing integer; invalid integer; pupils integer; BEGIN
IF NOT (public.has_role(auth.uid(),'super_admin') OR current_user='postgres' OR current_user='service_role') THEN RAISE EXCEPTION 'Administrator access required'; END IF;
SELECT count(*),count(*) FILTER(WHERE es.submitted_at IS NOT NULL) INTO sheets,done FROM public.exam_subjects es WHERE es.examination_id=_exam;
SELECT count(*) INTO missing FROM public.exam_subjects es JOIN public.teacher_assignments a ON a.id=es.assignment_id JOIN public.examinations e ON e.id=es.examination_id JOIN public.students s ON s.section_id=a.section_id AND s.session_id=e.session_id AND s.active LEFT JOIN public.marks m ON m.exam_subject_id=es.id AND m.student_id=s.id WHERE es.examination_id=_exam AND m.id IS NULL;
SELECT count(*) INTO invalid FROM public.marks m JOIN public.exam_subjects es ON es.id=m.exam_subject_id WHERE es.examination_id=_exam AND ((m.status='PRESENT' AND (m.obtained IS NULL OR m.obtained<0 OR m.obtained>es.max_marks OR (NOT es.allow_decimal AND m.obtained<>trunc(m.obtained)))) OR (m.status='EXEMPT' AND NOT es.allow_exempt));
SELECT count(DISTINCT s.id) INTO pupils FROM public.exam_subjects es JOIN public.teacher_assignments a ON a.id=es.assignment_id JOIN public.examinations e ON e.id=es.examination_id JOIN public.students s ON s.section_id=a.section_id AND s.session_id=e.session_id AND s.active WHERE es.examination_id=_exam;
RETURN jsonb_build_object('total',sheets,'submitted',done,'missing',missing,'invalid',invalid,'students',pupils,'ready',sheets>0 AND pupils>0 AND sheets=done AND missing=0 AND invalid=0); END $$;
REVOKE ALL ON FUNCTION public.exam_validation(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.exam_validation(uuid) TO authenticated,service_role;
CREATE FUNCTION public.write_marks(_sheet uuid,_entries jsonb,_submit boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE es public.exam_subjects; a public.teacher_assignments; e public.examinations; item jsonb; pupil public.students; n numeric; st text; admin boolean; BEGIN
SELECT * INTO es FROM public.exam_subjects WHERE id=_sheet FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Sheet not found'; END IF;
SELECT * INTO a FROM public.teacher_assignments WHERE id=es.assignment_id;
SELECT * INTO e FROM public.examinations WHERE id=es.examination_id FOR UPDATE;
admin:=public.has_role(auth.uid(),'super_admin'); IF NOT public.can_read_sheet(_sheet) THEN RAISE EXCEPTION 'Assigned teacher access required'; END IF;
IF e.status='PUBLISHED' THEN RAISE EXCEPTION 'Unpublish results before correcting marks'; END IF;
IF es.submitted_at IS NOT NULL AND NOT admin THEN RAISE EXCEPTION 'Submitted marks are locked'; END IF;
FOR item IN SELECT * FROM jsonb_array_elements(_entries) LOOP
SELECT * INTO pupil FROM public.students WHERE id=(item->>'student_id')::uuid AND section_id=a.section_id AND session_id=e.session_id AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Student not eligible for this sheet'; END IF;
st:=coalesce(item->>'status','PRESENT'); n:=CASE WHEN st='PRESENT' THEN (item->>'obtained')::numeric ELSE NULL END;
IF st NOT IN ('PRESENT','AB','EXEMPT') OR (st='PRESENT' AND (n IS NULL OR n<0 OR n>es.max_marks OR (NOT es.allow_decimal AND n<>trunc(n)))) OR (st='EXEMPT' AND NOT es.allow_exempt) THEN RAISE EXCEPTION 'Invalid marks or status'; END IF;
INSERT INTO public.marks(exam_subject_id,student_id,obtained,status) VALUES(_sheet,pupil.id,n,st) ON CONFLICT(exam_subject_id,student_id) DO UPDATE SET obtained=excluded.obtained,status=excluded.status,updated_at=now(); END LOOP;
IF _submit THEN
IF EXISTS(SELECT 1 FROM public.students s LEFT JOIN public.marks m ON m.student_id=s.id AND m.exam_subject_id=_sheet WHERE s.section_id=a.section_id AND s.session_id=e.session_id AND s.active AND m.id IS NULL) THEN RAISE EXCEPTION 'Every eligible student needs a mark or absence status'; END IF;
UPDATE public.exam_subjects SET submitted_at=now() WHERE id=_sheet; END IF;
INSERT INTO public.audit_logs(actor_id,action,details) VALUES(auth.uid(),CASE WHEN _submit THEN 'Marksheet submitted' ELSE 'Marks saved' END,jsonb_build_object('sheet',_sheet)); END $$;
REVOKE ALL ON FUNCTION public.write_marks(uuid,jsonb,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.write_marks(uuid,jsonb,boolean) TO authenticated;
CREATE FUNCTION public.publish_examination(_exam uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb; BEGIN
IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF;
PERFORM 1 FROM public.examinations WHERE id=_exam FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Exam not found'; END IF;
PERFORM 1 FROM public.exam_subjects WHERE examination_id=_exam FOR UPDATE;
v:=public.exam_validation(_exam); IF NOT (v->>'ready')::boolean THEN RAISE EXCEPTION 'Results incomplete: all subjects and eligible students must be validated'; END IF;
UPDATE public.examinations SET status='PUBLISHED',published_at=now(),scheduled_at=NULL WHERE id=_exam;
INSERT INTO public.marksheet_publications(examination_id,admin_id,action) VALUES(_exam,auth.uid(),'PUBLISHED');
INSERT INTO public.audit_logs(actor_id,action,details) VALUES(auth.uid(),'All results declared',jsonb_build_object('examination',_exam)); RETURN v; END $$;
REVOKE ALL ON FUNCTION public.publish_examination(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.publish_examination(uuid) TO authenticated;
CREATE FUNCTION public.portal_snapshot() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE role_name text; out_data jsonb; BEGIN
SELECT r.role::text INTO role_name FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=auth.uid() AND p.active ORDER BY CASE r.role WHEN 'super_admin' THEN 0 WHEN 'teacher' THEN 1 ELSE 2 END LIMIT 1;
IF role_name IS NULL THEN RAISE EXCEPTION 'No active school account assigned'; END IF;
SELECT jsonb_build_object('role',role_name,'profile',(SELECT to_jsonb(p) FROM public.profiles p WHERE p.id=auth.uid()),'sessions',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.academic_sessions x),'classes',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY level),'[]') FROM public.classes x),'sections',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.sections x),'subjects',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM public.subjects x),
'students',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') FROM public.students s WHERE role_name='super_admin' OR (role_name='teacher' AND public.is_assigned(s.section_id)) OR (role_name='student' AND s.profile_id=auth.uid() AND s.active)),
'teachers',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.teachers t WHERE role_name='super_admin' OR t.profile_id=auth.uid()),
'assignments',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM public.teacher_assignments a JOIN public.teachers t ON t.id=a.teacher_id WHERE role_name='super_admin' OR t.profile_id=auth.uid()),
'exams',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY start_date DESC),'[]') FROM public.examinations e),
'sheets',(SELECT coalesce(jsonb_agg(to_jsonb(es)),'[]') FROM public.exam_subjects es JOIN public.teacher_assignments a ON a.id=es.assignment_id JOIN public.examinations e ON e.id=es.examination_id WHERE public.can_read_sheet(es.id) OR (role_name='student' AND e.status='PUBLISHED' AND EXISTS(SELECT 1 FROM public.students s WHERE s.profile_id=auth.uid() AND s.section_id=a.section_id AND s.session_id=e.session_id AND s.active))),
'marks',(SELECT coalesce(jsonb_agg(to_jsonb(m)),'[]') FROM public.marks m JOIN public.exam_subjects es ON es.id=m.exam_subject_id JOIN public.examinations e ON e.id=es.examination_id JOIN public.students s ON s.id=m.student_id WHERE public.can_read_sheet(es.id) OR (role_name='student' AND s.profile_id=auth.uid() AND s.active AND e.status='PUBLISHED')),
'audit',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY created_at DESC),'[]') FROM (SELECT * FROM public.audit_logs WHERE role_name='super_admin' ORDER BY created_at DESC LIMIT 100) x)) INTO out_data;
IF role_name='super_admin' THEN out_data:=out_data || jsonb_build_object('validation',(SELECT coalesce(jsonb_object_agg(id::text,public.exam_validation(id)),'{}') FROM public.examinations)); END IF;
RETURN out_data; END $$;
REVOKE ALL ON FUNCTION public.portal_snapshot() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.portal_snapshot() TO authenticated;
CREATE FUNCTION public.demo_overview() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('students',(SELECT count(*) FROM public.students WHERE is_demo),'teachers',(SELECT count(*) FROM public.teachers WHERE is_demo),'classes',(SELECT count(*) FROM public.classes),'exams',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'name',e.name,'start_date',e.start_date,'end_date',e.end_date,'status',e.status,'total',(SELECT count(*) FROM public.exam_subjects WHERE examination_id=e.id),'submitted',(SELECT count(*) FROM public.exam_subjects WHERE examination_id=e.id AND submitted_at IS NOT NULL)) ORDER BY e.start_date DESC),'[]') FROM public.examinations e WHERE e.is_demo)) $$;
REVOKE ALL ON FUNCTION public.demo_overview() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.demo_overview() TO anon,authenticated;
CREATE FUNCTION public.reopen_sheet(_sheet uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; PERFORM 1 FROM public.examinations WHERE id=(SELECT examination_id FROM public.exam_subjects WHERE id=_sheet) FOR UPDATE; IF EXISTS(SELECT 1 FROM public.examinations WHERE id=(SELECT examination_id FROM public.exam_subjects WHERE id=_sheet) AND status='PUBLISHED') THEN RAISE EXCEPTION 'Unpublish examination first'; END IF; UPDATE public.exam_subjects SET submitted_at=NULL WHERE id=_sheet; INSERT INTO public.audit_logs(actor_id,action,details) VALUES(auth.uid(),'Marksheet reopened',jsonb_build_object('sheet',_sheet)); END $$;
REVOKE ALL ON FUNCTION public.reopen_sheet(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reopen_sheet(uuid) TO authenticated;
CREATE EXTENSION IF NOT EXISTS pg_cron;